import {simulate,COUNT,clamp} from './engine.js';
const $=id=>document.getElementById(id),worker=new Worker('./worker.js',{type:'module'});
const modes={neural:'双网络',pursuit:'恒速追逐',straight:'锁向直冲'};
let policies=null,groups=[],episodes=[],curves=[],generation=0,busy=false,ready=false,page=0,selected=null,frames=[],playTime=0,playing=false,lastTime=0,db=null,saveTimer,run=0,duelSeed=42,autoDuel=true,sessionKey='';
const settingIds=['mode','fixedSpeed','generations','seed','sigma','population','scenarios'];
function config(){return{mode:$('mode').value,fixedSpeed:+$('fixedSpeed').value,generations:clamp(Math.floor(+$('generations').value||1),1,500),seed:(+$('seed').value||0)>>>0,sigma:+$('sigma').value,population:clamp(Math.floor(+$('population').value||1),1,24),scenarios:clamp(Math.floor(+$('scenarios').value||1),1,12)};}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3300);}
function switchTab(tab){for(const t of ['arena','archive','rules'])$(t+'Tab').hidden=t!==tab;document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));if(tab==='archive')renderArchive();if(tab==='arena'){drawArena();drawChart();}}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
function modeUI(){const m=$('mode').value;$('fixedWrap').hidden=m==='neural';$('fixedValue').textContent=(+$('fixedSpeed').value).toFixed(1);$('sigmaValue').textContent=(+$('sigma').value).toFixed(2);$('modeHelp').textContent=m==='neural'?'双方网络交替更新，学习速度与方向控制。':m==='pursuit'?'速度恒定，始终追向当前位置；一局内规则不变。':'速度和目标朝向在开局锁定，一局内不变。';}
settingIds.forEach(id=>$(id).addEventListener('input',modeUI));
for(const id of ['mode','fixedSpeed','seed'])$(id).addEventListener('change',()=>{freshCurve(config());queueSave();});
function lockUI(){for(const id of [...settingIds,'reset','warm','importBtn'])$(id).disabled=busy;$('train').disabled=!ready;$('train').textContent=busy?'Ⅱ 停止训练':'▶ 开始训练';$('evaluate').disabled=busy||!ready;$('newDuel').disabled=busy||!ready;}
function checkpoint(){return{format:'arena-lab-v1',physics:'radius25-dt001-control01-omega1',config:config(),policies,generation,groups,curves,run,duelSeed,sessionKey,playRate:$('playRate').value};}
async function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('arena-lab',1);r.onupgradeneeded=()=>r.result.createObjectStore('experiments');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function save(){if(!db||!policies)return;try{const tx=db.transaction('experiments','readwrite');tx.objectStore('experiments').put(checkpoint(),'latest');await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=rej;});$('saveStatus').textContent='已自动保存到本浏览器';}catch{$('saveStatus').textContent='保存失败，请导出实验';}}
function queueSave(){clearTimeout(saveTimer);saveTimer=setTimeout(save,1500);}
function hydrate(data){groups=data.groups||[];episodes=[];for(const g of groups)for(let i=0;i<g.episodes.length;i++)episodes.push({g,index:i,number:episodes.length+1,...g.episodes[i]});curves=data.curves||[];generation=data.generation||0;policies=data.policies;run=data.run||0;duelSeed=data.duelSeed||42;sessionKey=data.sessionKey||'';for(const id of settingIds)if(data.config?.[id]!==undefined)$(id).value=data.config[id];modeUI();updateCounts();drawChart();renderRecent();const latest=curves.at(-1);if(latest){$('winRate').textContent=(latest.win*100).toFixed(0)+'%';$('testSummary').textContent=`8 局测试 · 平均用时 ${latest.time.toFixed(2)} s`;}if(data.playRate&&['0.5','1','2','4','8','16','32','64'].includes(String(data.playRate)))$('playRate').value=data.playRate;}
function updateCounts(){$('archiveCount').textContent=episodes.length;$('totalEpisodes').textContent=episodes.length.toLocaleString();$('generation').textContent=generation;}
function setScores(e){$('bullScore').textContent=e.bull.toFixed(1);$('runnerScore').textContent=e.runner.toFixed(1);$('bullBar').style.width=e.bull+'%';$('runnerBar').style.width=e.runner+'%';$('bullModel').textContent=e.g.config.mode==='neural'?'神经网络 / 追逐者':'固定规则 / '+modes[e.g.config.mode];$('scoreSource').textContent='第 '+e.number+' 局 · 最终';}
function selectEpisode(e,autoplay=true){if(!e)return;selected=e;const result=simulate(e.g.bull,e.g.runner,e.g.config,e.seed,true);frames=result.frames;playTime=0;playing=autoplay;$('play').textContent=playing?'Ⅱ':'▶';$('episodeTitle').textContent=`第 ${e.number} 局 · ${e.g.phase} · G${e.g.generation} · 种子 ${e.seed}`;setScores(e);drawArena();}
function addGroup(g){groups.push(g);for(let i=0;i<g.episodes.length;i++)episodes.push({g,index:i,number:episodes.length+1,...g.episodes[i]});updateCounts();renderRecent();if(g.phase==='演示'||!selected)selectEpisode(episodes.at(-1));if(!$('archiveTab').hidden)renderArchive();queueSave();}
worker.onmessage=({data:d})=>{if(d.type==='ready'){policies={bull:d.bull,runner:d.runner};ready=true;lockUI();$('trainStatus').textContent='就绪 · 等待训练';if(autoDuel){autoDuel=false;newDuel();}queueSave();}if(d.type==='group')addGroup(d.item);if(d.type==='busy'){busy=d.busy;lockUI();if(!busy){$('trainStatus').textContent='训练已停止 · 权重已保留';$('trainPercent').textContent='';queueSave();}}if(d.type==='progress'){$('trainStatus').textContent=`G${d.generation} · ${d.role==='bull'?'斗牛':'斗牛士'} · ${d.candidate}/${d.total}`;const p=100*d.candidate/d.total;$('trainPercent').textContent=Math.round(p)+'%';$('trainProgress').style.width=p+'%';}if(d.type==='generation'){generation=d.generation;policies={bull:d.bull,runner:d.runner};curves.push(d.metrics);$('winRate').textContent=(d.metrics.win*100).toFixed(0)+'%';$('testSummary').textContent=`8 局测试 · 平均用时 ${d.metrics.time.toFixed(2)} s`;updateCounts();drawChart();const e=episodes.at(-1);if(e?.g.phase==='测试')selectEpisode(e);queueSave();}if(d.type==='evaluated'){$('winRate').textContent=(d.win*100).toFixed(0)+'%';$('testSummary').textContent=`额外 8 局 · 斗牛 ${d.bull.toFixed(1)} / 斗牛士 ${d.runner.toFixed(1)}`;selectEpisode(episodes.at(-1));toast('8 局独立测试完成');}if(d.type==='error'){busy=false;lockUI();toast('训练异常：'+d.message);}};
worker.onerror=e=>{busy=false;ready=false;lockUI();toast('计算线程加载失败，请通过本地服务器打开项目。');};
function freshCurve(c){const key=`${c.mode}/${c.fixedSpeed}/${c.seed}`;if(sessionKey!==key){curves=[];sessionKey=key;drawChart();$('winRate').textContent='—';$('testSummary').textContent='新配置 · 等待测试';}}
$('train').onclick=()=>{if(busy){worker.postMessage({type:'stop'});$('trainStatus').textContent='正在完成当前候选…';return;}const c=config();freshCurve(c);busy=true;lockUI();worker.postMessage({type:'train',config:c});};
$('evaluate').onclick=()=>{const c=config();freshCurve(c);worker.postMessage({type:'evaluate',config:c,run:++run});};
function newDuel(){if(!ready||busy)return;const c=config();worker.postMessage({type:'duel',config:c,seed:(c.seed+duelSeed++*997)>>>0});}
$('newDuel').onclick=newDuel;
$('finishReplay').onclick=()=>{if(!frames.length)return;playing=false;playTime=frames.at(-1).t;$('play').textContent='▶';drawArena();};
$('continuous').onchange=()=>{if($('continuous').checked&&!playing&&!busy)newDuel();};
$('reset').onclick=()=>{ready=false;generation=0;curves=[];lockUI();updateCounts();drawChart();$('winRate').textContent='—';$('testSummary').textContent='网络已重置 · 历史对局保留';autoDuel=true;worker.postMessage({type:'reset',seed:config().seed,warm:$('warm').checked});};
$('play').onclick=()=>{if(!frames.length)return;if(playTime>=frames.at(-1).t)playTime=0;playing=!playing;$('play').textContent=playing?'Ⅱ':'▶';};
$('scrub').oninput=()=>{if(!frames.length)return;playing=false;$('play').textContent='▶';playTime=+$('scrub').value/1000*frames.at(-1).t;drawArena();};$('trail').onchange=drawArena;$('playRate').onchange=queueSave;
function canvasContext(id){const c=$(id),r=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1;if(r.width<1||r.height<1)return null;const w=Math.round(r.width*dpr),h=Math.round(r.height*dpr);if(c.width!==w||c.height!==h){c.width=w;c.height=h;}const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);return{ctx,w:r.width,h:r.height};}
function drawArena(){const c=canvasContext('arena');if(!c)return;const{ctx,w,h}=c,cx=w/2,cy=h/2+9,r=Math.min(w/2-40,h/2-24),scale=r/25;const P=p=>[cx+p.x*scale,cy-p.y*scale];ctx.save();ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fillStyle='#f0f4ec';ctx.fill();ctx.clip();ctx.strokeStyle='#dfe7dc';ctx.lineWidth=.6;for(let i=-25;i<=25;i+=5){ctx.beginPath();ctx.moveTo(cx+i*scale,cy-r);ctx.lineTo(cx+i*scale,cy+r);ctx.stroke();ctx.beginPath();ctx.moveTo(cx-r,cy+i*scale);ctx.lineTo(cx+r,cy+i*scale);ctx.stroke();}ctx.strokeStyle='#cfdbce';ctx.setLineDash([3,5]);for(const d of [8,16,24]){ctx.beginPath();ctx.arc(cx,cy,d*scale,0,Math.PI*2);ctx.stroke();}ctx.setLineDash([]);ctx.restore();ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.strokeStyle='#b8cbb6';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#91a18f';ctx.font='8px Segoe UI';ctx.textAlign='center';ctx.fillText('+y',cx,cy-r-9);ctx.fillText('+x',cx+r+13,cy+3);ctx.fillText('−25',cx-r,cy+r+14);ctx.fillText('0',cx,cy+r+14);ctx.fillText('25 m',cx+r,cy+r+14);if(!frames.length)return;let index=frames.findIndex(f=>f.t>=playTime);if(index<0)index=frames.length-1;const s=frames[index];if($('trail').checked){for(const [key,color]of[['b','#dc875e'],['m','#449c88']]){ctx.beginPath();for(let i=0;i<=index;i++){const[x,y]=P(frames[i][key]);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.strokeStyle=color;ctx.globalAlpha=.65;ctx.lineWidth=1.6;ctx.stroke();ctx.globalAlpha=1;const[x,y]=P(frames[0][key]);ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.strokeStyle=color;ctx.stroke();}}const[bX,bY]=P(s.b),[mX,mY]=P(s.m);ctx.setLineDash([3,4]);ctx.strokeStyle='#aebdad';ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(bX,bY);ctx.lineTo(mX,mY);ctx.stroke();ctx.setLineDash([]);for(const[key,color]of[['b','#db744a'],['m','#177c68']]){const p=s[key],[x,y]=P(p);ctx.beginPath();ctx.arc(x,y,key==='b'?Math.max(1.5,.4*scale):9,0,Math.PI*2);ctx.fillStyle=color+'18';ctx.fill();ctx.beginPath();ctx.arc(x,y,4.2,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='white';ctx.lineWidth=1.7;ctx.stroke();ctx.beginPath();ctx.moveTo(x+7*Math.cos(p.h),y-7*Math.sin(p.h));ctx.lineTo(x+16*Math.cos(p.h),y-16*Math.sin(p.h));ctx.strokeStyle=color;ctx.lineWidth=1.6;ctx.stroke();ctx.font='9px Microsoft YaHei';ctx.fillStyle=color;ctx.textAlign='left';ctx.fillText(key==='b'?'斗牛':'斗牛士',x+11,y+17);}$('clock').textContent=s.t.toFixed(2).padStart(5,'0');const d=Math.hypot(s.b.x-s.m.x,s.b.y-s.m.y);$('distance').innerHTML=d.toFixed(2)+' <small>m</small>';$('minimum').innerHTML=s.min.toFixed(2)+' <small>m</small>';$('bullSpeed').innerHTML=s.b.v.toFixed(2)+' <small>m/s</small>';$('runnerSpeed').innerHTML=s.m.v.toFixed(2)+' <small>m/s</small>';$('scrub').value=1000*playTime/frames.at(-1).t;$('resultBadge').hidden=!s.done;$('resultBadge').textContent=s.caught?'斗牛捕获成功 · '+s.t.toFixed(2)+' s':'斗牛士成功逃逸 · 30.00 s';}
function drawChart(){const c=canvasContext('chart');if(!c)return;const{ctx,w,h}=c,L=30,R=w-14,T=10,B=h-23;ctx.font='8px Segoe UI';ctx.textAlign='right';for(let n=0;n<=100;n+=25){const y=B-n/100*(B-T);ctx.fillStyle='#a4b0a4';ctx.fillText(n,L-8,y+3);ctx.strokeStyle='#edf1e9';ctx.beginPath();ctx.moveTo(L,y);ctx.lineTo(R,y);ctx.stroke();}$('chartEmpty').hidden=curves.length>0;const shown=curves.slice(-100);for(const[key,color]of[['bull','#db744a'],['runner','#177c68']]){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();shown.forEach((v,i)=>{const x=shown.length===1?(L+R)/2:L+i/(shown.length-1)*(R-L),y=B-v[key]/100*(B-T);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();shown.forEach((v,i)=>{if(shown.length>30&&i%5!==0&&i!==shown.length-1)return;const x=shown.length===1?(L+R)/2:L+i/(shown.length-1)*(R-L),y=B-v[key]/100*(B-T);ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,2.4,0,Math.PI*2);ctx.fill();});}if(shown.length){ctx.fillStyle='#91a18f';ctx.textAlign='left';ctx.fillText('G'+shown[0].generation,L,h-3);ctx.textAlign='right';ctx.fillText('G'+shown.at(-1).generation,R,h-3);}}
function renderRecent(){const recent=episodes.slice(-4).reverse();$('recent').innerHTML=recent.length?recent.map(e=>`<div class="recent-item"><div><strong>#${String(e.number).padStart(4,'0')} <span class="pill ${e.caught?'caught':''}">${e.caught?'捕获':'逃逸'}</span></strong>${e.g.phase} · ${e.time.toFixed(2)} s</div><span>${e.bull.toFixed(1)} / ${e.runner.toFixed(1)}</span><button class="text-button" data-replay="${e.number}">回放 ↗</button></div>`).join(''):'<p class="help">第一场对抗即将开始</p>';}
function renderArchive(){const f=$('filter').value,filtered=episodes.filter(e=>f==='全部'||e.g.phase===f).reverse(),pages=Math.max(1,Math.ceil(filtered.length/20));page=clamp(page,0,pages-1);$('archiveRows').innerHTML=filtered.slice(page*20,page*20+20).map(e=>`<tr><td>#${String(e.number).padStart(4,'0')}</td><td>${e.g.phase} / G${e.g.generation}</td><td>${modes[e.g.config.mode]}</td><td><span class="pill ${e.caught?'caught':''}">${e.caught?'斗牛捕获':'斗牛士逃逸'}</span></td><td>${e.time.toFixed(2)} s</td><td class="orange">${e.bull.toFixed(1)}</td><td class="teal">${e.runner.toFixed(1)}</td><td><button class="text-button" data-replay="${e.number}">回放 →</button></td></tr>`).join('')||'<tr><td colspan="8">此分类暂无对局</td></tr>';$('pageInfo').textContent=`${page+1} / ${pages} · 共 ${filtered.length} 局`;$('prev').disabled=page===0;$('next').disabled=page===pages-1;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-replay]');if(b){selectEpisode(episodes[+b.dataset.replay-1]);switchTab('arena');}});$('filter').onchange=()=>{page=0;renderArchive();};$('prev').onclick=()=>{page--;renderArchive();};$('next').onclick=()=>{page++;renderArchive();};
$('exportBtn').onclick=()=>{if(!policies)return;const blob=new Blob([JSON.stringify(checkpoint())],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`arena-lab-G${generation}-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出权重、全部对局和学习曲线');};
$('importBtn').onclick=()=>$('fileInput').click();
function validate(d){const nums=a=>Array.isArray(a)&&a.length===COUNT&&a.every(v=>Number.isFinite(v)&&Math.abs(v)<1e6);const cfg=c=>c&&Object.hasOwn(modes,c.mode)&&Number.isFinite(c.fixedSpeed)&&c.fixedSpeed>=0&&c.fixedSpeed<=8&&Number.isFinite(c.seed)&&Number.isFinite(c.generations)&&Number.isFinite(c.sigma)&&Number.isFinite(c.population)&&Number.isFinite(c.scenarios);if(d.format!=='arena-lab-v1'||d.physics!=='radius25-dt001-control01-omega1'||!nums(d.policies?.bull)||!nums(d.policies?.runner)||!cfg(d.config)||!Number.isInteger(d.generation)||!Array.isArray(d.groups)||!Array.isArray(d.curves))throw Error('文件格式或网络权重不匹配');for(const g of d.groups){if(!nums(g.bull)||!nums(g.runner)||!cfg(g.config)||!['训练','测试','演示'].includes(g.phase)||!Number.isInteger(g.generation)||!Array.isArray(g.episodes))throw Error('对局档案无效');for(const e of g.episodes)if(!Number.isInteger(e.seed)||!['bull','runner','time','min'].every(k=>Number.isFinite(e[k]))||typeof e.caught!=='boolean')throw Error('对局数据无效');}for(const c of d.curves)if(!['bull','runner','generation','win','time'].every(k=>Number.isFinite(c[k])))throw Error('曲线数据无效');}
$('fileInput').onchange=async()=>{const file=$('fileInput').files[0];if(!file)return;try{if(file.size>100*1024*1024)throw Error('文件超过 100 MB');const d=JSON.parse(await file.text());validate(d);hydrate(d);ready=false;lockUI();worker.postMessage({type:'load',...policies,generation});if(episodes.length)selectEpisode(episodes.at(-1),false);toast('已恢复实验，可继续训练');queueSave();}catch(e){toast('导入失败：'+e.message);}$('fileInput').value='';};
window.addEventListener('resize',()=>{drawArena();drawChart();});document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});
function animate(now){if(playing&&frames.length){playTime+=Math.min((now-lastTime)/1000,.15)*+$('playRate').value;if(playTime>=frames.at(-1).t){playTime=frames.at(-1).t;playing=false;$('play').textContent='▶';if($('continuous').checked&&!busy)setTimeout(()=>{if($('continuous').checked&&!busy)newDuel();},250);}drawArena();}lastTime=now;requestAnimationFrame(animate);}requestAnimationFrame(animate);
modeUI();drawArena();drawChart();try{db=await openDB();const saved=await new Promise((res,rej)=>{const r=db.transaction('experiments').objectStore('experiments').get('latest');r.onsuccess=()=>res(r.result);r.onerror=rej;});if(saved){validate(saved);hydrate(saved);autoDuel=false;worker.postMessage({type:'load',...policies,generation});selectEpisode(episodes.at(-1),false);$('saveStatus').textContent='已恢复本地实验';}else worker.postMessage({type:'init',seed:42});}catch{worker.postMessage({type:'init',seed:42});$('saveStatus').textContent='本地存储不可用，请导出实验';}
